INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Grand Battle!', 'From TV Animation One Piece: Grand Battle! is a Japanese fighting video game developed by Ganbarion and published by Bandai. It is the first game in the One Piece: Grand Battle series and the second game to be based on the One Piece manga and anime. This game''s introduction uses the theme song We Are! (ウィーアー! Wī Ā!) from the One Piece Anime.' FROM games WHERE igdb_id = 75738 ON CONFLICT (game_id, language_code) DO NOTHING;
