INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 2002', '#1 for a reason! Return to glory: Relive the golden days of 16-bit Madden gameplay in Madden Classic mode. Kick off the season with the newest NFL team: Take the field with all 32 NFL teams including the expansion Houston Texans. A game within a game: Run or defend an improved 2-Minute Drill, now featuring Head-To-Head Challenge. Bang-Boom-Pow: Perfect the X''s and O''s with the help of John Madden in Training mode.' FROM games WHERE igdb_id = 3539 ON CONFLICT (game_id, language_code) DO NOTHING;
