INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CoLoBot', 'Original mix of adventure and educational game. While you have fun with this game, you will also learn C-BOT, program language that is similar to all C- languages. C-BOT wouldn''t allow you to write programs, but it will ease learning of C- languages.' FROM games WHERE igdb_id = 80574 ON CONFLICT (game_id, language_code) DO NOTHING;
