INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Adventure 2: Battle', 'Sonic Adventure 2: Battle is a complete conversion of Sonic Adventure 2 from the Dreamcast with additional features. Exclusive to the Gamecube are improved visuals, new 2 player battle games (including Kart Racing, Hunting and Chao Karate) and the ability to grow your Chao and exchange them to the Game Boy Advance game Sonic Advance for portable training.' FROM games WHERE igdb_id = 7862 ON CONFLICT (game_id, language_code) DO NOTHING;
