INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom vs. SNK 2: Mark of the Millennium 2001', 'Capcom vs. SNK 2: Mark of the Millennium 2001 (Millionaire Fighting 2001 in Japan) is the sequel to the fighting game Capcom vs SNK, and the sixth game in the Capcom''s VS. Series. This game was released on Sega NAOMI hardware in the arcade. It was later released for the Sega Dreamcast (Japan only) PlayStation 2 and Playstation 3 (as a Playstation 2 Classics title in the PlayStation Network), with the GameCube and Xbox receiving an updated version called Capcom vs. SNK 2 EO.' FROM games WHERE igdb_id = 3846 ON CONFLICT (game_id, language_code) DO NOTHING;
