INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tekken Advance', 'Tekken Advance is a fighting game released for the Game Boy Advance. It is non-canonical to the Tekken storyline, but follows the events of Tekken 3. It uses sprites based on Tekken 3''s 3D models for its characters and was the first Tekken game to be released on a Nintendo platform.' FROM games WHERE igdb_id = 1240 ON CONFLICT (game_id, language_code) DO NOTHING;
