INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot: The Wrath of Cortex', 'Crash Bandicoot: The Wrath of Cortex is the fourth mainline series game and the first to feature Crash Bandicoot on the PlayStation 2. It was later ported to the GameCube and Xbox, making it his first multiplatform appearance. The player controls Crash and his younger sister Coco who must gather 25 crystals and defeat the main antagonists of the story, Doctor Neo Cortex and his new super weapon Crunch Bandicoot. Much of the game takes place in a Virtual Reality Hub System created by Coco to help Crash gather the crystals. The gameplay is similar to the older games of the series.' FROM games WHERE igdb_id = 1188 ON CONFLICT (game_id, language_code) DO NOTHING;
