INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballistics', 'Ballistics is a futuristic racing computer game developed by Grin and published by Xicat Interactive in 2001. Grin developed an arcade version of the game, released in 2002 featuring a unique reclined seating position cabinet by Triotech Amusement. Players race across seven different tracks in various leagues against other competitors on high-speed hoverbikes.
