INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Tarzan: Untamed', 'Picking up quite a while after the defeat of Clayton, Jane and Professor Porter now speak Gorilla-language fluently and Jane is married to Tarzan. However, their lives are threatened once again by a brutal band of British explorers led by the unscrupulous Oswald Gardner, who becomes fascinated with Tarzan and strives to capture the ape-man and take him back to England as a media attraction.' FROM games WHERE igdb_id = 10625 ON CONFLICT (game_id, language_code) DO NOTHING;
