INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ico', 'An action-adventure game in which a boy is abandoned and taken to a massive castle by his people. After exploring it for a while, he meets a girl who speaks a different language than him, then decides to get both of them out of the castle grounds by leading her along, in order to escape the shadow-like creatures that frequently try to kidnap the girl.' FROM games WHERE igdb_id = 7170 ON CONFLICT (game_id, language_code) DO NOTHING;
