INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castlevania-circle-of-the-moon', 1132, '2001-03-21', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobcr5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vgn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Circle of the Moon', 'Castlevania: Circle of the Moon is the first of the series to be based on the action/RPG structure of Castlevania:Symphony of the Night rather than the level-based action style of all previous Castlevania games. Dracula''s castle is a single continuous building, and as Nathan discovers artifacts within it he gains new abilities that allow him to explore more of it. While Nathan can only use his Killer Whip as a weapon, he can find and equip different kinds of armor and accessories that change his stats. Unique to this entry in the series is the Dual Set-up System, where a combination of two cards will give Nathan unique magical abilities. For example, equipping a fire type card with a whip card will give the Killer Whip a fire attribute, while equipping it with a summon card will let Nathan summon a fire demon to attack onscreen enemies.' FROM games WHERE igdb_id = 1132 ON CONFLICT (game_id, language_code) DO NOTHING;
