INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal: Black', 'Twisted Metal: Black is a vehicle combat video game developed by Incognito Entertainment (formerly Incog Inc.) and published by Sony Computer Entertainment America for the PlayStation 2 video game console. It is the fifth installment to the Twisted Metal series and was released June 18, 2001. An online enabled multiplayer-only variant, Twisted Metal: Black Online, was released later as a free update.' FROM games WHERE igdb_id = 5413 ON CONFLICT (game_id, language_code) DO NOTHING;
