INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal: Small Brawl', 'Twisted Metal: Small Brawl is a vehicular combat game in which the player takes control of one of twelve unique remote control vehicles. While in control of a vehicle, the player can accelerate, steer, brake, reverse, activate the turbo, turn tightly, toggle between and activate weapons using the game controller''s d-pad, analog sticks and buttons.' FROM games WHERE igdb_id = 5417 ON CONFLICT (game_id, language_code) DO NOTHING;
