INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jak and Daxter: The Precursor Legacy', 'Jak and Daxter: The Precursor Legacy is a 2001 platform video game developed by Naughty Dog and published by Sony Computer Entertainment for the Sony PlayStation 2 on December 4, 2001, as the first game of the Jak and Daxter series. The game follows the protagonist, a young teenager named Jak, as he tries to help his friend Daxter after he is transformed into an "ottsel", a fictional hybrid of an otter and a weasel.
