INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! The Duelists of the Roses', 'Yu-Gi-Oh! The Duelists of the Roses is a video game developed by Konami based on the Yu-Gi-Oh! manga and anime series. Its main characters, Yugi Mutou and Seto Kaiba, play opposing teams known as the Lancastrians and the Yorkists. Each team is playable, battling various characters throughout the plot to prevent a ritual summoning by using sorcerous rose cards.' FROM games WHERE igdb_id = 4630 ON CONFLICT (game_id, language_code) DO NOTHING;
