INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania Chronicles', 'The 2D whip-wielding action game Castlevania returns with a classic version never before seen in America with Castlevania Chronicles. Count Dracula has been resurrected to begin a new reign of terror across the land. As Simon Belmont, descendant of legendary vampire hunters, you enter Dracula''s estate to face the Count and his minions - alone. Be prepared for one of the first adventures in the Castlevania series ever!' FROM games WHERE igdb_id = 19468 ON CONFLICT (game_id, language_code) DO NOTHING;
