INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! The Eternal Duelist Soul', 'Yu-Gi-Oh! The Eternal Duelist Soul is a Yu-Gi-Oh! video game for the Game Boy Advance. It is the international version of Yu-Gi-Oh! Duel Monsters 5 Expert 1. Gameplay is similar to standard dueling rules, except that the Side Deck allows less than 15 cards, and is more for convenience of getting to cards for your Deck than switching between duels, as CPU duels are single duels rather than matches (with some exceptions in events).' FROM games WHERE igdb_id = 11672 ON CONFLICT (game_id, language_code) DO NOTHING;
