INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onimusha: Warlords', 'Onimusha: Warlords is an epic saga of 16th century Japan inspired by the battle scenes of famed Japanese director Akira Kurosawa. It takes place in a world of darkness and magic when power hungry warlords battle for control of Feudal Japan. One brave Samurai, Samanosuke Akechi, boldly volunteers to rescue the kidnapped princess Yuki, but does not fully realize the desperation of this mission. An entire legion of demon warriors stands between him and his mission to avenge the princess.' FROM games WHERE igdb_id = 5845 ON CONFLICT (game_id, language_code) DO NOTHING;
