INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anarchy Online', 'Anarchy Online (AO) is a science fiction themed massive multiplayer online roleplaying game (MMORPG) set almost 30,000 years into the future, in an age where common surgical implants and microscopic nano-bots can relieve most forms of human suffering or transform any normal being into a weapon of destructive force.' FROM games WHERE igdb_id = 1996 ON CONFLICT (game_id, language_code) DO NOTHING;
