INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('project-eden', 8941, '2001-10-08', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1q73.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8c8b.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Eden', 'Due to severe overpopulation, the planet Earth’s diameter is increasing with the growth of towering mega-cities, each inhabited by millions of humans. Buildings are growing ever-upwards, interconnected with a thick web of roads, walkways and service channels. In these giant human hives, only the affluent may feel the rays of the sun and breathe the cleaner air. Your team has been selected to go down and investigate problems at the Real Meat factory, in which all of the equipment has started to simultaneously malfunction. Technicians sent to repair the machinery have gone missing without explanation. The UPA''s (Urban Protection Agency) orders are clear: prepare for the descent.
