INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runaway: A Road Adventure', 'Runaway: A Road Adventure is a point and click adventure game developed by Péndulo Studios, S.L. in 2001. The game follows the long tradition of two-dimensional adventure games like the first two installments of the Broken Sword series. It enjoyed immense popularity in countries like Germany and France, where the adventure genre is still popular.' FROM games WHERE igdb_id = 278 ON CONFLICT (game_id, language_code) DO NOTHING;
