INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mystery of the Druids', 'In this classic adventure, you will take on the role of young Scotland Yard Detective Brent Halligan, assigned to solve the puzzle surrounding a mysterious order of Druids and a series of gruesome murders. It appears that the neo-Druids are conducting ritual killings in order to conjure up incredibly sinister forces.' FROM games WHERE igdb_id = 12449 ON CONFLICT (game_id, language_code) DO NOTHING;
