INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alone in the Dark: The New Nightmare', 'Alone in the Dark: The New Nightmare is the fourth installment in the survival horror video game series Alone in the Dark. The player can choose which of the two protagonists to play as. Carnby’s side of the plot focuses mainly on fighting monsters through physical means, while Aline’s is more centered on puzzle-solving. The two occasionally meet, and the main plot areas intersect.' FROM games WHERE igdb_id = 1960 ON CONFLICT (game_id, language_code) DO NOTHING;
