INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Syphon Filter 3', 'Syphon Filter 3 is a third-person shooter developed by Bend Studio and published by Sony Computer Entertainment. Released in November 2001 for the PlayStation, it is the third instalment in the Syphon Filter series. The game continues the story of secret agents Gabe Logan and Lian Xing as they are interrogated by a Senate committee about their previous missions. The narrative unfolds through flashbacks, revealing their battles against international conspiracies and bioterrorism.' FROM games WHERE igdb_id = 4117 ON CONFLICT (game_id, language_code) DO NOTHING;
