INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens versus Predator 2', 'The sequel to one of the most frightening games ever made, Aliens vs. Predator 2 takes you to Planet LV1201, where three diverse and bloodthirsty species battle for survival. The story-driven plot weaves together the fates of all three races, while the action is as heart-stopping as the blockbuster films on which it is based. Choose to play as Alien, Predator, or Marine as you use your physical prowess, killer instincts, or superior firepower to stay alive.' FROM games WHERE igdb_id = 594 ON CONFLICT (game_id, language_code) DO NOTHING;
