INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom vs. SNK: Millennium Fight 2000 Pro', 'An updated version of the original Capcom vs. SNK titled Capcom vs. SNK Pro was released on the Arcade Sega NAOMI GD-ROM hardware (2000), Dreamcast (2001) and PlayStation (2002), the latter suffering from slight load times between rounds and downgraded graphics and sound due to hardware limitations. New additions included Joe Higashi (from Fatal Fury) and Dan Hibiki (from Street Fighter Alpha), new moves for existing characters, and new modes of play.' FROM games WHERE igdb_id = 45829 ON CONFLICT (game_id, language_code) DO NOTHING;
