INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('z-steel-soldiers', 3276, '2001-06-15', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48s4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a1mehzygjvtknc50hgfp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z: Steel Soldiers', 'Lead your Z: Steel Soldiers into the next century rebooted for the rocket fueled fans of the classic hard-core strategy game. In the bloody aftermath of ‘Z’ comes Z: Steel Soldiers. All your favourite strategies and gameplay from the classic version, with graphics that have powered into the 21st century, vivid 3D landscapes, and a state of the art engine that brings your game to life. Meet the new breed of robots, with a taste for war and a warped sense of humour. Z: Steel Soldiers.' FROM games WHERE igdb_id = 3276 ON CONFLICT (game_id, language_code) DO NOTHING;
