INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shenmue-ii', 1218, '2001-09-06', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2raf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/huxyaiedwg0ezm9hydqt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shenmue II', 'Yu Suzuki''s cinematic masterpiece returns with more spellbinding adventure and an even more immersive world. The epic continues as Ryo Hazuki arrives in Hong Kong on his quest to avenge his father''s murder by the warlord Lan Di and unravel the mystery of the Phoenix mirror. Set in Hong Kong, Kowloon, and Guilin, you''ll travel through breathtaking scenery, rich with mountainous wilderness, traditional Taoist temples, and stunning tropical landscapes. As you move through massive, highly-detailed 3D worlds, you''ll interact with almost every facet of your environment as well as a whole new cast of characters.
