INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcanum: of Steamworks and Magick Obscura', 'Imagine a place of wonder,where magic and technology hold equal sway, and an adventurer might just as easily wield a flintlock pistol as a flaming sword. A place where great industrial cities house castle keeps and factories, home to Dwarves, Humans, Orcs and Elves alike. A place of ancient runes and steamworks, of magic and machines, of sorcery and science.
