INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-trek-deep-space-nine-dominion-wars', 3282, '2001-06-12', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e9b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wpucrbr7cuxyq0coeucv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Deep Space Nine - Dominion Wars', 'Raging through the final two seasons of Star Trek: Deep Space Nine, the Dominion War pitted an alliance of the Federation and Klingons against the Cardassians and invading Dominion fleets in a prolonged and costly battle for control of the Alpha Quadrant. Now you can join this epic struggle as you take tactical, strategic and navigational command of any one of the four battling forces. With unprecedented access to all facets of space combat, Star Trek: Deep Space Nine Dominion Wars asks YOU to decide who lives or dies. Strategize! Maneuver! Anticipate! And when you''ve got your enemy where you want him -- Strike!
