INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Racers 2', 'LEGO Racers, start your engines! Rocket Racer is back and he''s teamed up with the toughest competitors in the galaxy to bring racers of all ages this awesome challenge. Players must win their races, keep their cars on the road and muster all their adventure racing skills to find and collect the elusive Golden Bricks.' FROM games WHERE igdb_id = 390 ON CONFLICT (game_id, language_code) DO NOTHING;
