INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun: Combat Zones', 'Jump into the cockpits of the Navy''s top planes with Top Gun: Combat Zones. With the F-14, F-18, and F-22 under your control, you must embark on dangerous low-level missions throughout hazardous canyons and across vast cityscapes. Eliminate ground or air targets in Southeast Asia, Gulf States, Arctic Circle, and Miramar Base.' FROM games WHERE igdb_id = 9236 ON CONFLICT (game_id, language_code) DO NOTHING;
