INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Galactic Battlegrounds', 'The destiny of a galaxy hangs in the balance, and you are in command. Lead the great armies of the Star Wars: Episode II: Attack of the Clones saga in intense real-time strategy clashes. Enter the fray as the Galactic Empire, Rebel Alliance, Wookies, Trade Federation, Gungans or Royal Naboo to determine the course of the Galactic Civil War.' FROM games WHERE igdb_id = 139 ON CONFLICT (game_id, language_code) DO NOTHING;
