INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('conker-s-bad-fur-day', 1286, '2001-03-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uq6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2o45.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conker''s Bad Fur Day', 'Humorous action-platformer that does away with the tedious item collection found in most games in the genre. Instead, BFD employs a combination of standard jump, run and explore mechanics and context-sensitive gags and actions. For instance, in the beginning of the game, by pressing the B button on the first pad he encounters, Conker drinks some Alka-Seltzer to wipe out his hangover, at which point players can proceed forward. Later on these pads are used to activate a slingshot and throwing knives; to turn Conker into an anvil and drop downward; to shoot automatic, double-handed guns; to activate a The Matrix-inspired slow-motion effect and flip through the air shooting enemies; and much, much more.' FROM games WHERE igdb_id = 1286 ON CONFLICT (game_id, language_code) DO NOTHING;
