INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoo Tycoon', 'Zoo Tycoon is a business simulation developed by Blue Fang Games and released by Microsoft Game Studios. It is a tycoon game in which the player must run a zoo and try to make a profit. Although first released for Microsoft Windows and Macintosh in 2001, it was ported to the Nintendo DS in 2005. It was followed by two expansion packs, Zoo Tycoon: Dinosaur Digs and Zoo Tycoon: Marine Mania, which were released in 2002, as well as a sequel, Zoo Tycoon 2, released in 2004.' FROM games WHERE igdb_id = 334 ON CONFLICT (game_id, language_code) DO NOTHING;
