INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2002', 'NHL 2002 is a video game released by EA Sports in 2001. It is the predecessor to NHL 2003. The game''s cover man is Pittsburgh Penguins superstar and owner Mario Lemieux, who had just made a stunning comeback after being retired for three and a half years. It was the first installment of the NHL series to be released on Xbox.' FROM games WHERE igdb_id = 815 ON CONFLICT (game_id, language_code) DO NOTHING;
