INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cel-damage', 3852, '2001-11-15', 51, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fbyxuz34nry2cwslgipp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cel Damage', 'Imagine a world where ''toons rule the road and the demolition derby is a way of life. In Cel Damage, the world''s toughest ''toons face off against each other in souped-up, weapon-laden vehicles to out-maneuver, out-race, and out-smack each other for personal glory. These gas-powered gladiators battle it out in highly interactive cartoon environments where they can roam freely, discover hidden areas, interact with set gag pieces (such as the 100 ton weight), perform stunts, and whack the heck out of their opponents. And with a host of wild weapons, such as giant boxing gloves and baseball bats, at their disposal, these ''toons with attitude take part in vehicular combat as it has never been seen before.' FROM games WHERE igdb_id = 3852 ON CONFLICT (game_id, language_code) DO NOTHING;
