INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motor City Online', 'In this online-only game, you buy classic cars, customize their performance to your liking, and race them against opponents around the world. The game was plagued with technical issues and met its end in August 29th 2003.' FROM games WHERE igdb_id = 23809 ON CONFLICT (game_id, language_code) DO NOTHING;
