INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inspector Gadget: Gadget''s Crazy Maze', 'Inspector Gadget: Gadget''s Crazy Maze isn''t the type of game one would expect when taking on the role of the bumbling, multi-functional detective of the 1980''s cartoon. Rather than an action title like its Game Boy Color counterpart, this incarnation of Inspector Gadget is best described as a puzzle game with limited action elements.
