INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TransWorld Surf', 'TransWorld Surf lets you pull off all the massive airs and blazing tailslides of professional surfers, including Taj Burrow, Andy Irons, and Shane Dorian. This is your chance to drop into more than 20 of the world''s most challenging breaks in locations such as Todos Santos, Hossegor, and Tavarua. Conquer the waves with a friend, hitch a ride with the Reef Girls, watch out for the hungry sharks, and remember to save your best moves for photographers who just may put you on the in-game cover of TransWorld Surf.' FROM games WHERE igdb_id = 4209 ON CONFLICT (game_id, language_code) DO NOTHING;
