INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnivores: Ice Age', 'Carnivores: Ice Age is a first-person shooter video game developed by Action Forms, and later ported to iOS and Android devices by Tatem Games. It is the third game in the Carnivores series. Unlike the previous games, in which the player must hunt dinosaurs, Carnivores: Ice Age allows the player to stalk large Cenozoic mammals such as mammoths and saber-toothed cats.' FROM games WHERE igdb_id = 20566 ON CONFLICT (game_id, language_code) DO NOTHING;
