INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '911 Fire Rescue', '911 Fire Rescue is a first-person "Douser" that pits you against raging fires. You run into burning buildings with your fire hose to put out fires and rescue trapped victims. The game is set in houses and buildings, simulating smoke that blurs your vision and burns your lungs. The missions require you to find the people trapped inside.' FROM games WHERE igdb_id = 71612 ON CONFLICT (game_id, language_code) DO NOTHING;
