INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moorhen-3-the-chicken-chase', 49438, '2001-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coakhf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6x46.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moorhen 3: The Chicken Chase!', 'This really couldn''t be any simpler; Moorhen features no complicated gameplay whatsoever. You just shoot things. The real skill though is in knowing just what to shoot and when to shoot it and where some targets reap sizeable rewards others will drain your score in no time at all. One addition to version three is the introduction of protected birds flying around with your intended targets which means that shooting now takes a little more thought than simply blasting into the sky. Other features remain intact and there are still items that need to be avoided such as balloons and various animals on the ground. As usual though you''ll need to experiment to find out just what''s worth hitting and what''s not.
