INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gangsters 2: Vendetta', 'Set from late 1928-early 1929, the game follows a character called ''Joey Bane'' whose nickname is decided by the player e.g. Joey ''Scarface'' Bane. The character''s father is murdered at the beginning by a mob controlling most of New Temperance, the leader of the mob is Frankie ''Hammer'' Constantine. The player progresses through the game by defeating different gangs and gang leaders that are all connected to the killing of Joey Bane''s father.' FROM games WHERE igdb_id = 51226 ON CONFLICT (game_id, language_code) DO NOTHING;
