INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Age of Camelot', 'Dark Age of Camelot is a 3D medieval fantasy MMORPG that combines Arthurian lore, Norse mythology and Irish Celtic legends with a dash of high fantasy. It is set in the period after King Arthur''s death and his kingdom has split into three parts which are in a constant state of war with each other. DAoC includes both PvE and RvR combat, players can choose to adventure alone or join groups to get completion of credit in large-scale PvE encounters and for communication purposes in RvR.' FROM games WHERE igdb_id = 657 ON CONFLICT (game_id, language_code) DO NOTHING;
