INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie: Explorer', 'Explore the world with Barbie. Travel to Tibet, Egypt, and the African jungle on a mission to find four ancient, jeweled treasures. Run, jump, swing, climb, and dive to avoid obstacles and deadly pitfalls in a race to unlock the secrets of the Mystic Mirror. Travel only with Barbie or bring a friend, as this game supports up to two players.' FROM games WHERE igdb_id = 3314 ON CONFLICT (game_id, language_code) DO NOTHING;
