INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kohan: Immortal Sovereigns', 'A real-time strategy game set in a fantasy world where you take on the role of an immortal known as the Kohan. Your race once ruled the world but was devastated in a series of massive cataclysms. As an immortal, you have reawakened to a new world unlike the one you once knew. Now you must come to grips with your past glory, your present hardship, and your future destiny. If you are to return your race to their rightful glory, you must solve the mystery of their destruction.' FROM games WHERE igdb_id = 767 ON CONFLICT (game_id, language_code) DO NOTHING;
