INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WTA Tour Tennis', 'Use the amazing combo of moves provided to outwit the world''s great female players. Also, this game features different court surfaces, which also affect the bounce and spin of the ball. Singles and Double friendlies can be played against any of the WTA stars. Four major tournaments are offered, success in which will see the player rising through the WTA ranks.' FROM games WHERE igdb_id = 4569 ON CONFLICT (game_id, language_code) DO NOTHING;
