INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forever Kingdom', 'Darius, whose family was murdered when he was young, goes on a journey to avenge his family. His best friend Ruyan and an girl named Faeana who suffers from amnesia joins him on his journey. The player controls one party member out of 3 to engage enemies. The game again features the coordination rating system and a variety of fun equipment which was welcomed in the original Evergrace.' FROM games WHERE igdb_id = 10907 ON CONFLICT (game_id, language_code) DO NOTHING;
