INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trainz', 'Trainz is a series of 3D train simulator video games. The simulators consist of route and session editors called Surveyor, and the Driver module, that loads a route and lets the player operate and watch the trains run, either in "DCC" mode or "CAB" mode.' FROM games WHERE igdb_id = 920 ON CONFLICT (game_id, language_code) DO NOTHING;
