INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zwei!!: The Arges Adventure', 'Boasting a completely standalone story set on a mysterious “low fantasy” island floating amongst the clouds, Zwei: The Arges Adventure plays out as a classically styled action-oriented 2D dungeon crawler with oodles of optional content and unlockables, player-defined challenge through a unique food-based experience system, and a pervading tongue-in-cheek humor style that helps set it apart from other entries in the genre.' FROM games WHERE igdb_id = 61631 ON CONFLICT (game_id, language_code) DO NOTHING;
